// Visualising the regions with flags:
// -Xms512m           initial heap size
// -Xmx2g             max heap size
// -Xmn256m           young generation size (or -XX:NewRatio=3 → Old:Young = 3:1)
// -XX:SurvivorRatio=8 → Eden:Survivor = 8:1:1
// -XX:MaxMetaspaceSize=256m

// Print heap region sizes at startup:
// -XX:+PrintFlagsFinal | grep -E 'HeapSize|NewSize|MetaspaceSize'

// Runtime query:
Runtime rt = Runtime.getRuntime();
long usedMB = (rt.totalMemory() - rt.freeMemory()) / 1_048_576;
long maxMB  = rt.maxMemory() / 1_048_576;
System.out.printf("Used: %d MB / Max: %d MB%n", usedMB, maxMB);

// Check tenuring threshold in use:
// -XX:+PrintTenuringDistribution (Java < 17)
// -Xlog:gc+age=debug  (Java 17+)

// Example log output:
// Desired survivor size 26214400 bytes, new threshold 7 (max: 15)
// - age 1: 4048 bytes
// - age 3: 24123456 bytes   ← bulk of survivors
// - age 7: 1024 bytes       ← being promoted next GC

// Force immediate promotion for known large objects:
// -XX:PretenureSizeThreshold=512k
// Objects >= 512 KB allocate directly in Old Gen

// 1. Heap OOM — enable heap dump on crash:
// -XX:+HeapDumpOnOutOfMemoryError
// -XX:HeapDumpPath=/tmp/heap.hprof

// 2. GC overhead limit (can disable, but only to buy time):
// -XX:-UseGCOverheadLimit   ← not recommended in production

// 3. Metaspace — diagnose classloader leak:
java.lang.management.MemoryMXBean mem =
    ManagementFactory.getMemoryMXBean();
MemoryUsage heap    = mem.getHeapMemoryUsage();
MemoryUsage nonHeap = mem.getNonHeapMemoryUsage();
System.out.println("Metaspace used: " + nonHeap.getUsed() / 1024 / 1024 + " MB");

// 4. Check direct buffer usage:
BufferPoolMXBean direct = ManagementFactory
    .getPlatformMXBeans(BufferPoolMXBean.class)
    .stream().filter(b -> b.getName().equals("direct"))
    .findFirst().orElseThrow();
System.out.println("Direct: " + direct.getMemoryUsed() / 1024 / 1024 + " MB");

// Select GC algorithm:
// -XX:+UseParallelGC        Parallel (throughput)
// -XX:+UseG1GC              G1 (balanced — Java 9+ default)
// -XX:+UseZGC               ZGC (sub-ms pauses, Java 15+)
// -XX:+UseShenandoahGC      Shenandoah
// -XX:+UseSerialGC          Serial (single-threaded, tiny heaps)

// G1 pause target:
// -XX:MaxGCPauseMillis=100  (soft target, not a guarantee)

// ZGC with generational mode (Java 21+, much better throughput):
// -XX:+UseZGC -XX:+ZGenerational

// Print GC algorithm in use:
// -Xlog:gc*=info:file=gc.log:time,uptime:filecount=5,filesize=20m

// Tune G1 region size (normally auto):
// -XX:G1HeapRegionSize=16m

// Humongous threshold is always 50% of region size.
// With 16MB regions, objects >= 8MB are Humongous.
// Avoid frequent large allocations — they fragment the heap.

// Adjust how many Old regions are collected in Mixed GC:
// -XX:G1MixedGCCountTarget=8    (spread Old reclaim over 8 cycles)
// -XX:G1HeapWastePercent=5      (stop Mixed GC when < 5% reclaimable)

// If you see 'to-space exhausted' in GC log:
// → Young Gen is too full to absorb survivors
// → Increase heap or reduce -XX:G1NewSizePercent

// G1 GC log interpretation (Java 17+):
// [gc] GC(42) Pause Young (Normal) (G1 Evacuation Pause) 512M->480M(2048M) 45.123ms
//              ↑ trigger             ↑ type               before→after(max)  pause time

// Enable ZGC (Java 15 GA):
// -XX:+UseZGC

// Enable Generational ZGC (Java 21, highly recommended):
// -XX:+UseZGC -XX:+ZGenerational

// ZGC has no fixed pause target flag — pauses are inherently low.
// Tune max heap generously; ZGC needs headroom to relocate concurrently:
// -Xmx4g   (ZGC works best with >= 2x the live data set)

// ZGC does NOT compact the heap during STW — it relocates objects
// concurrently. This means:
// ✓ Pause = mark start + mark end + relocate start (~< 1ms each)
// ✗ Higher CPU overhead than G1 (~15-20% throughput cost)

// Monitor ZGC:
// -Xlog:gc*:file=zgc.log
// Look for: [gc] GC(5) Garbage Collection (Proactive) 1200M(29%)->800M(19%)

// Heap headroom rule of thumb:
// Live set = 1GB → use -Xmx3g minimum for ZGC

// Measure live set size:
// 1. Trigger Full GC (in dev/staging only):
jmap -histo:live <pid>   // forces Full GC, prints histogram

// Or via JMX:
ManagementFactory.getMemoryMXBean().gc();
long liveBytes = ManagementFactory.getMemoryMXBean()
    .getHeapMemoryUsage().getUsed();

// 2. From GC log after Full GC line:
// [gc] GC(100) Pause Full (Ergonomics) 800M->320M(1024M) 2.3s
//                                        ↑ live set = 320MB

// Sizing formula:
// -Xmx = live_set × 4      for G1 / Parallel
// -Xmx = live_set × 5      for ZGC (needs more headroom)

// If live set = 320 MB:
// G1 → -Xmx1280m (round to -Xmx1536m)
// ZGC → -Xmx1600m (round to -Xmx2g)

// Monitor live set drift over time with Prometheus jvm_memory_used_bytes

// 1. Static collection leak:
class Registry {
    private static final Map<String, Session> sessions = new HashMap<>();
    // BAD: sessions never evicted
    // FIX: use Guava Cache or Caffeine with expiry:
    // Cache<String, Session> sessions = Caffeine.newBuilder()
    //     .expireAfterAccess(30, MINUTES).maximumSize(10_000).build();
}

// 2. ThreadLocal leak (common in thread pools / Tomcat):
class RequestContext {
    private static final ThreadLocal<User> current = new ThreadLocal<>();
    public static void set(User u) { current.set(u); }
    // FIX: always clear in finally:
    //   try { set(user); handle(request); } finally { current.remove(); }
}

// 3. Listener leak:
class EventSource {
    private final List<Listener> listeners = new ArrayList<>();
    public void addListener(Listener l) { listeners.add(l); }
    // FIX: also provide removeListener(), or use WeakReference<Listener>
}

// 4. Classloader leak — avoid storing Class<?> in static fields across deployments

# Capture heap dump (live process):
jmap -dump:format=b,live,file=heap.hprof <pid>

# Or trigger on OOM automatically:
-XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=/tmp/

# Or via jcmd (preferred in Java 11+):
jcmd <pid> GC.heap_dump /tmp/heap.hprof

// MAT workflow:
// 1. Open heap.hprof in Eclipse MAT
// 2. Run "Leak Suspects Report" → finds top retained-heap culprits
// 3. Inspect "Dominator Tree" → who is keeping what alive
// 4. Use OQL to query: SELECT * FROM java.util.HashMap$Entry WHERE ...

// VisualVM live workflow:
// 1. Attach to running JVM
// 2. Monitor tab → watch Heap Used over time
// 3. If heap grows without returning to baseline after GC → leak
// 4. Sampler → Memory → see allocation by class

# async-profiler allocation profiling (no overhead of heap dump):
./asprof -d 30 -e alloc -f alloc.html <pid>

// Soft reference cache (survives GC unless heap is low):
SoftReference<BufferedImage> imageCache =
    new SoftReference<>(loadExpensiveImage());
BufferedImage img = imageCache.get(); // may return null after GC
if (img == null) img = loadExpensiveImage(); // reload

// Weak reference (for canonical maps, metadata association):
WeakReference<Widget> ref = new WeakReference<>(widget);
// widget can be GC'd; ref.get() returns null after collection

// WeakHashMap — keys are weak references:
Map<Object, Metadata> meta = new WeakHashMap<>();
// Entry removed automatically when key is GC'd
// WARNING: do not use when you want the map to keep the key alive

// Phantom reference with ReferenceQueue (for cleanup):
ReferenceQueue<Resource> queue = new ReferenceQueue<>();
PhantomReference<Resource> phantom = new PhantomReference<>(res, queue);
// After res is GC'd, phantom is enqueued — poll queue to run cleanup

// Java 9+ Cleaner (preferred over finalizers and PhantomRef directly):
Cleaner cleaner = Cleaner.create();
cleaner.register(res, () -> closeNativeResource());
